<template>
  <div class="fill-height">
    <PaginatedCards :config="paginatedCardsConfig" />
    <AddExpenseDialog v-if="addExpenseDialog.isOpen" />
    <AddOtherExpenseDialog v-if="addOtherExpenseDialog.isOpen" />
  </div>
</template>

<script>
import { mapState, mapGetters, mapActions } from 'vuex'

import expensesViewActions from '@/store/expensesView/actions.types'

import setConfig from '@/components/ExpensesView/ExpensesList/config'
import PaginatedCards from '@/components/shared/PaginatedCards'
import AddExpenseDialog from '@/components/ExpensesView/AddExpenseDialog'
import AddOtherExpenseDialog from '@/components/ExpensesView/AddOtherExpenseDialog'

export default {
  name: 'PaginatedCardsList',
  components: { PaginatedCards, AddExpenseDialog, AddOtherExpenseDialog },
  computed: {
    ...mapState('app', ['windowSize', 'sidebarOpened']),
    ...mapState('expenses', ['fetching']),
    ...mapState('expensesView', ['addExpenseDialog', 'addOtherExpenseDialog']),
    ...mapGetters('expenses', ['getFilteredData']),
    paginatedCardsConfig() {
      return setConfig(
        {
          items: this.getFilteredData,
          windowHeight: this.windowSize.y,
          windowWidth: this.windowSize.x,
          sidebarOpened: this.sidebarOpened,
          currentCardComponent: 'ExpenseCard',
          fetching: this.fetching,
        },
        {
          openAddExpenseDialog: this.openAddExpenseDialog,
        }
      )
    },
  },
  methods: {
    ...mapActions('expensesView', [
      expensesViewActions.setAddExpenseDialogStatus,
      expensesViewActions.setAddOtherExpenseDialogStatus,
    ]),
    openAddExpenseDialog(expense) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Expenses',
        screen: 'ExpenseCard',
        name: `Open add ${expense.name} expense`,
      })
      if (expense.name === 'otherExpenses') {
        this[expensesViewActions.setAddOtherExpenseDialogStatus](true)
        return
      }
      const data = {
        isOpen: true,
        selectedExpense: expense,
      }
      this[expensesViewActions.setAddExpenseDialogStatus](data)
    },
  },
}
</script>
