const config = (state, methods) => {
  return {
    state,
    methods,
    groupClass: 'pr-4',
    groups: [
      {
        id: 'filters-group-01',
        controls: [
          {
            id: 'search-control',
            type: 'input',
            label: 'expensesView.toolbar.searchField.label',
            placeholder: 'expensesView.toolbar.searchField.placeholder',
            icon: 'mdi-magnify',
            backgroundColor: 'cardBackgroundSecondary',
            color: 'primary',
            ref: 'expense-input-search',
            group: 'search',
            onChange: value => methods.setSearchTerm(value),
          },
        ],
      },
    ],
  }
}

export default config
