import ExpenseCard from '@/components/shared/ExpenseCard'

import light from '@/themes/light'
import dark from '@/themes/dark'

export const setConfig = (state, methods) => ({
  state,
  methods: {
    ...methods,
    onClick: expense => methods.openAddExpenseDialog(expense),
    onDblClick: () => null,
  },
  containerRef: 'expenses-view__expenses-list',
  title: 'expensesView.expensesList.title',
  titleClass: 'pl-2',
  icon: 'mdi-cash',
  loaderColor: { light: light.productLoader, dark: dark.productLoader },
  isDetail: false,
  rowsPerPage: 4,
  page: 1,
  cardComponents: {
    ExpenseCard: {
      cardOffsetHeight: 190,
      component: ExpenseCard,
      itemsPerRow: {
        small: 4,
        medium: 4,
        large: 4,
        extraLarge: 4,
      },
    },
  },
  noDataMessage: {
    icon: 'mdi-plus-circle',
    messages: [
      'customersView.listView.noData.firstMessage',
      'customersView.listView.noData.secondMessage',
    ],
  },
})

export default setConfig
