<template>
  <v-container fluid class="expenses-view" id="expenses-view">
    <!-- View toolbar  -->
    <v-row no-gutters>
      <v-col
        class="expenses-view__filter-toolbar px-6 pt-6"
        id="expenses-view__filter-toolbar"
      >
        <ExpensesToolbar />
      </v-col>
    </v-row>
    <!-- List view -->
    <v-row no-gutters>
      <v-col
        class="expenses-view__expenses-list"
        id="expenses-view__expenses-list"
        :style="{
          height: `calc(100vh - ${getExpensesListStyles}px)`,
        }"
      >
        <ExpensesList />
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { formatNumberToDb } from '@/tools/numbersFormat'
import { getTranslatedText } from '@/tools/data'
import { getAppLayoutHeaderAndFooterHeight } from '@/tools/view'

import expensesActions from '@/store/expenses/actions.types'

import ExpensesToolbar from '@/components/ExpensesView/ExpensesToolbar'
import ExpensesList from '@/components/ExpensesView/ExpensesList'

export default {
  name: 'Expenses',
  components: { ExpensesToolbar, ExpensesList },
  data() {
    return { layoutCommonElementsHeight: 0 }
  },
  computed: {
    ...mapState('expenses', ['data']),
    ...mapState('usersView', ['selectedUser', 'estimatedCash']),
    getExpensesListStyles() {
      return this.layoutCommonElementsHeight
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('expenses', [expensesActions.fetchExpenses]),
    getLayoutHeight() {
      const layoutComponentsHeight = getAppLayoutHeaderAndFooterHeight(
        'expenses-view'
      )
      const expensesViewToolbar = document.getElementById(
        'expenses-view__filter-toolbar'
      ).offsetHeight
      this.layoutCommonElementsHeight =
        layoutComponentsHeight + expensesViewToolbar
    },
    getEstimatedCash() {
      const stateEstimatedCash =
        this.estimatedCash === null || this.estimatedCash === undefined
          ? 0
          : this.estimatedCash
      return formatNumberToDb(stateEstimatedCash)
    },
  },
  mounted() {
    if (this.data.expenses.length < 1)
      this[expensesActions.fetchExpenses](this.getTranslatedText)
    this.getLayoutHeight()
  },
}
</script>

<style lang="scss" scoped>
.expenses-view {
  height: 100%;
  .expenses-view__filter-toolbar {
    background-color: var(--v-mainBackground-base);
  }
  .expenses-view__expenses-list {
    width: 100%;
  }
}
</style>
