<template>
  <div>
    <DialogCard :config="componentConfig.dialogData">
      <Form :config="componentConfig" />
      <template v-slot:footer>
        <MultipleButtons :config="componentConfig.multipleButtons" />
      </template>
    </DialogCard>
    <ExternalCashRegisterInfo @userHasBeenInformed="addExpense(true)" />
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import EXPENSES_DB_API_EVENTS from '@/config/events/databaseAPI/expensesEvents'

import { cleanObjectObserver, getTranslatedText } from '@/tools/data'
import { formatNumberToDb, formatNumberFromDb } from '@/tools/numbersFormat'

import i18n from '@/plugins/i18n'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import usersViewActions from '@/store/usersView/actions.types'
import expensesViewActions from '@/store/expensesView/actions.types'
import appActions from '@/store/app/actions.types'

import setConfig from '@/components/ExpensesView/AddOtherExpenseDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'
import MultipleButtons from '@/components/shared/MultipleButtons'
import ExternalCashRegisterInfo from '@/components/shared/ExternalCashRegisterInfo'

export default {
  name: 'AddOtherExpenseDialog',
  components: { ExternalCashRegisterInfo, MultipleButtons, DialogCard, Form },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      addingExpense: false,
    }
  },
  computed: {
    ...mapState('expensesView', ['addOtherExpenseDialog']),
    ...mapState('usersView', ['estimatedCash', 'selectedUser']),
    ...mapState('account', ['data']),
    componentConfig() {
      return setConfig(
        {
          opened: this.addOtherExpenseDialog.isOpen,
          inputs: this.inputs,
          v: this.$v.inputs,
          limits: this.data.country.limits,
          appIsInEn: i18n.locale === 'en',
        },
        {
          closeDialog: this.closeDialog,
          showInfoDialog: this.showInfoDialog,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('expensesView', [
      expensesViewActions.setAddOtherExpenseDialogStatus,
    ]),
    ...mapActions('usersView', [usersViewActions.setUserEstimatedCash]),
    ...mapActions('app', [appActions.toggleExternalCashRegisterInfoDialog]),
    setProperties: function() {
      this.componentConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    showInfoDialog(isFromExternalCashRegister = false) {
      if (this.addingExpense === true) return
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }
      if (!isFromExternalCashRegister) {
        this.addExpense(isFromExternalCashRegister)
        return
      }
      this[appActions.toggleExternalCashRegisterInfoDialog](true)
    },
    addExpense(isFromExternalCashRegister) {
      this.addingExpense = true
      rendererEventsService.send(EXPENSES_DB_API_EVENTS.channel, {
        event: EXPENSES_DB_API_EVENTS.events.addExpense.name,
        data: {
          expense: {
            id: 11,
            name: this.inputs.concept,
          },
          amount: formatNumberToDb(this.inputs.amount),
          userId: this.selectedUser.id,
          estimatedCash: this.getEstimatedCash(),
          isFromExternalCashRegister,
        },
      })
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$reset())
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this[expensesViewActions.setAddOtherExpenseDialogStatus](false)
    },
    getEstimatedCash() {
      const stateEstimatedCash =
        this.estimatedCash === null || this.estimatedCash === undefined
          ? 0
          : this.estimatedCash
      return formatNumberToDb(stateEstimatedCash)
    },
    expenseListener(event, payload) {
      const replies = {
        [EXPENSES_DB_API_EVENTS.events.addExpense.replies.error]: () => {
          this.closeDialog()
          notificationsService.showError(
            'notification.expenses.errorAdding',
            this.$vuetify.lang
          )
          this.addingExpense = false
        },
        [EXPENSES_DB_API_EVENTS.events.addExpense.replies.success]: () => {
          this[usersViewActions.setUserEstimatedCash](
            formatNumberFromDb(payload.data.estimatedCash)
          )
          notificationsService.showSuccess(
            'notification.expenses.added',
            this.$vuetify.lang,
            {},
            [this.inputs.concept]
          )
          this.closeDialog()
          this.addingExpense = false
        },
      }
      replies[payload.event]()
    },
  },
  validations() {
    return this.validators
  },
  mounted: async function() {
    this.setProperties()
    rendererEventsService.subscribe(
      EXPENSES_DB_API_EVENTS.replyChannel,
      this.expenseListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      EXPENSES_DB_API_EVENTS.replyChannel,
      this.expenseListener
    )
  },
}
</script>
