import {
  required,
  decimal,
  maxLength,
  maxValue,
} from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-calculator',
    title: 'expensesView.expensesList.otherExpenses',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    messages: ['expensesView.addExpenseDialog.othersMessage'],
    height: 380,
    maxWidth: state.appIsInEn ? 570 : 500,
    id: 'add-other-expense-amount-form',
    onClickCancel: () => methods.closeDialog(),
  },
  fields: [
    {
      id: 'amount',
      type: 'input',
      valueType: 'number',
      label: 'shared.amount',
      errorMessage: 'starterLayout.openRegister.errorAmount',
      color: 'primaryColor',
      required: true,
      autofocus: true,
      validators: {
        required,
        decimal,
        maxValue: maxValue(state.limits.maxValuePackagePrice),
      },
    },
    {
      id: 'concept',
      type: 'input',
      label: 'shared.concept',
      errorMessage: 'expensesView.addExpenseDialog.conceptErrorMessage',
      required: true,
      validators: { required, maxLength: maxLength(50) },
    },
  ],
  multipleButtons: [
    {
      ref: 'cancelButton',
      color: 'accent',
      onClick: () => methods.closeDialog(),
      text: 'shared.cancel',
    },
    {
      tooltip: {
        text: 'expensesView.addExpenseDialog.payExternalCashRegister',
      },
      ref: 'externalCashRegister',
      color: 'primary',
      onClick: () => methods.showInfoDialog(true),
      text: 'expensesView.addExpenseDialog.externalCashRegister',
    },
    {
      tooltip: {
        text: 'expensesView.addExpenseDialog.payMainCashRegister',
      },
      ref: 'mainCashRegister',
      color: 'primary',
      onClick: () => methods.showInfoDialog(),
      text: 'expensesView.addExpenseDialog.mainCashRegister',
    },
  ],
  id: 'add-other-expense-amount-form',
})

export default setConfig
