<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapState, mapActions } from 'vuex'

import expensesViewActions from '@/store/expensesView/actions.types'

import config from '@/components/ExpensesView/ExpensesToolbar/Filters/config'
import ToolBar from '@/components/shared/ToolBar'

export default {
  name: 'ExpensesFilter',
  components: { ToolBar },
  data() {
    return { config }
  },
  computed: {
    ...mapState('customersView', ['filters']),
    componentConfig: function() {
      return config(
        { filters: this.filters },
        { setSearchTerm: this[expensesViewActions.setSearchTermFilter] }
      )
    },
  },
  methods: {
    ...mapActions('expensesView', [expensesViewActions.setSearchTermFilter]),
  },
}
</script>
