<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapGetters, mapActions } from 'vuex'

import helpCategories from '@/config/helpCategories'

import helpCenterViewActions from '@/store/helpCenterView/actions.types'

import config from '@/components/ExpensesView/ExpensesToolbar/Operations/config'
import ToolBar from '@/components/shared/ToolBar'

export default {
  name: 'CustomersOperations',
  components: { ToolBar },
  data() {
    return { config }
  },
  computed: {
    ...mapGetters('helpCenter', ['getFilteredData']),
    componentConfig: function() {
      return config({ videos: this.getFilteredData }, {})
    },
  },
  methods: {
    ...mapActions('helpCenterView', [helpCenterViewActions.setVideoTypeFilter]),
  },
  mounted() {
    this[helpCenterViewActions.setVideoTypeFilter]([helpCategories.expenses])
  },
  beforeDestroy() {
    this[helpCenterViewActions.setVideoTypeFilter]([])
  },
}
</script>
