import { required, decimal, maxValue } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: state.expense.icon,
    title: `expensesView.expensesList.${state.expense.name}`,
    titleBackground: '#white',
    titleColor: 'textPrimary',
    messages: ['expensesView.addExpenseDialog.message'],
    extraValuesMessages: [state.expense.text],
    height: 300,
    maxWidth: state.appIsInEn ? 570 : 500,
    id: 'add-expense-amount-form',
    onClickCancel: () => methods.closeDialog(),
  },
  fields: [
    {
      id: 'amount',
      type: 'input',
      valueType: 'number',
      label: 'shared.amount',
      errorMessage: 'starterLayout.openRegister.errorAmount',
      color: 'primaryColor',
      required: true,
      autofocus: true,
      validators: {
        required,
        decimal,
        maxValue: maxValue(state.limits.maxValuePackagePrice),
      },
    },
  ],
  multipleButtons: [
    {
      ref: 'cancelButton',
      color: 'accent',
      onClick: () => {
        methods.track({
          type: 'interaction',
          action: 'click',
          category: 'Expenses',
          screen: 'AddExpenseDialog',
          name: 'Close dialog',
        })
        methods.closeDialog()
      },
      text: 'shared.cancel',
    },
    {
      tooltip: {
        text: 'expensesView.addExpenseDialog.payExternalCashRegister',
      },
      ref: 'externalCashRegister',
      color: 'primary',
      onClick: () => methods.showInfoDialog(true),
      text: 'expensesView.addExpenseDialog.externalCashRegister',
    },
    {
      tooltip: {
        text: 'expensesView.addExpenseDialog.payMainCashRegister',
      },
      ref: 'mainCashRegister',
      color: 'primary',
      onClick: () => methods.showInfoDialog(),
      text: 'expensesView.addExpenseDialog.mainCashRegister',
    },
  ],
  id: 'add-expense-amount-form',
})

export default setConfig
