<template>
  <ToolbarContainer :config="componentConfig" />
</template>

<script>
import config from '@/components/ExpensesView/ExpensesToolbar/config'
import ToolbarContainer from '@/components/shared/ToolbarContainer'

export default {
  name: 'ExpensesViewMainToolbar',
  components: { ToolbarContainer },
  data() {
    return { config }
  },
  computed: {
    componentConfig() {
      return config()
    },
  },
}
</script>
